    <title>Image preview - delete confirmation</title>
    <style>
      :root {
        color-scheme: dark;
        --color-bg: #0b1020;
        --color-panel: #121a2f;
        --color-panel-strong: #18223f;
        --color-text: #eef2ff;
        --color-muted-text: #b4c0e0;
        --color-border: #34405f;
        --color-focus: #8ab4ff;
        --color-danger: #ff6b81;
        --color-danger-strong: #ff4d67;
        --color-success: #7ee0a7;
        --color-shadow: #030712;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #1b2750 0%, var(--color-bg) 45%),
          var(--color-bg);
        color: var(--color-text);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-220%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--color-text);
        color: #050816;
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .shell {
        width: min(100%, 72rem);
        margin: 0 auto;
        padding: 2rem 1.25rem 4rem;
      }

      header {
        margin-bottom: 2rem;
      }

      .eyebrow {
        display: inline-block;
        margin-bottom: 0.75rem;
        padding: 0.35rem 0.75rem;
        border: 1px solid var(--color-border);
        border-radius: 999px;
        color: var(--color-muted-text);
        font-size: 0.875rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0;
        max-width: 42rem;
        color: var(--color-muted-text);
        font-size: 1.05rem;
      }

      main {
        outline: none;
      }

      .preview-layout {
        display: grid;
        gap: 1.5rem;
      }

      .preview-card {
        display: grid;
        gap: 1.25rem;
        padding: clamp(1rem, 2vw, 1.5rem);
        border: 1px solid var(--color-border);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, var(--color-panel-strong), var(--color-panel));
        box-shadow: 0 1.5rem 4rem -2rem var(--color-shadow);
      }

      figure {
        margin: 0;
      }

      .image-frame {
        overflow: hidden;
        border: 1px solid var(--color-border);
        border-radius: 1.25rem;
        background: #0f172a;
      }

      img {
        display: block;
        width: 100%;
        height: auto;
        aspect-ratio: 4 / 3;
        object-fit: cover;
      }

      figcaption {
        margin-top: 1rem;
        color: var(--color-muted-text);
        line-height: 1.5;
      }

      .meta {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      .meta span {
        padding: 0.5rem 0.8rem;
        border-radius: 999px;
        background: #0d1428;
        border: 1px solid var(--color-border);
        color: var(--color-muted-text);
        font-size: 0.95rem;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      button {
        border: 1px solid transparent;
        border-radius: 0.9rem;
        padding: 0.9rem 1.2rem;
        font: inherit;
        font-weight: 700;
        color: var(--color-text);
        cursor: pointer;
        transition:
          transform 120ms ease,
          border-color 120ms ease,
          background-color 120ms ease;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:active {
        transform: translateY(0);
      }

      button:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid var(--color-focus);
        outline-offset: 3px;
      }

      .button-secondary {
        background: #0d1428;
        border-color: var(--color-border);
      }

      .trigger,
      .button-danger {
        background: linear-gradient(180deg, var(--color-danger), var(--color-danger-strong));
        color: #19050a;
      }

      .trigger[disabled] {
        cursor: not-allowed;
        opacity: 0.65;
        transform: none;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--color-success);
        font-weight: 600;
      }

      dialog {
        width: min(92vw, 30rem);
        padding: 0;
        border: 1px solid var(--color-border);
        border-radius: 1.25rem;
        background: linear-gradient(180deg, #11182d, #0c1224);
        color: var(--color-text);
        box-shadow: 0 2rem 5rem -2rem var(--color-shadow);
      }

      dialog::backdrop {
        background: rgb(3 7 18 / 0.72);
        backdrop-filter: blur(4px);
      }

      .dialog-body {
        padding: 1.5rem;
      }

      .dialog-body h2 {
        margin: 0 0 0.75rem;
        font-size: 1.5rem;
      }

      .dialog-body p {
        margin: 0;
        color: var(--color-muted-text);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      .removed .image-frame,
      .removed figcaption,
      .removed .meta {
        opacity: 0.38;
      }

      .removed .image-frame {
        position: relative;
      }

      .removed .image-frame::after {
        content: "Removed from library";
        position: absolute;
        inset: auto 1rem 1rem 1rem;
        padding: 0.8rem 1rem;
        border-radius: 0.9rem;
        background: #08111f;
        border: 1px solid var(--color-border);
        color: var(--color-text);
        font-weight: 700;
        text-align: center;
      }

      @media (max-width: 40rem) {
        .dialog-actions,
        .actions {
          flex-direction: column;
        }

        .dialog-actions button,
        .actions button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --color-bg: Canvas;
          --color-panel: Canvas;
          --color-panel-strong: Canvas;
          --color-text: CanvasText;
          --color-muted-text: CanvasText;
          --color-border: ButtonBorder;
          --color-focus: Highlight;
          --color-danger: ButtonFace;
          --color-danger-strong: ButtonFace;
          --color-success: CanvasText;
          --color-shadow: Canvas;
        }

        .skip-link,
        button,
        dialog,
        .preview-card,
        .image-frame,
        .meta span {
          border: 1px solid ButtonBorder;
          box-shadow: none;
        }

        .trigger,
        .button-danger,
        .button-secondary,
        .skip-link {
          background: ButtonFace;
          color: ButtonText;
        }

        dialog::backdrop {
          background: rgb(0 0 0 / 0.8);
          backdrop-filter: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div class="shell">
      <header>
        <span class="eyebrow">Library preview</span>
        <h1>Image preview</h1>
        <p class="intro">
          Review this image before deciding whether to keep it in your library.
          Deleting the image opens a confirmation dialog.
        </p>
      </header>

      <main id="maincontent" tabindex="-1">
        <section class="preview-layout" aria-labelledby="image-details-heading">
          <div class="preview-card" id="imageCard">
            <h2 id="image-details-heading">Evening dune light</h2>
            <figure>
              <div class="image-frame">
                <img
                  id="previewImage"
                  alt="Golden light moving across layered desert dunes under a deep blue evening sky."
                  src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 900'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0%25' stop-color='%230c2d68'/%3E%3Cstop offset='100%25' stop-color='%234f7fd5'/%3E%3C/linearGradient%3E%3ClinearGradient id='duneA' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0%25' stop-color='%23d7924d'/%3E%3Cstop offset='100%25' stop-color='%23704625'/%3E%3C/linearGradient%3E%3ClinearGradient id='duneB' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0%25' stop-color='%23f2c078'/%3E%3Cstop offset='100%25' stop-color='%23a85f2b'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='900' fill='url(%23sky)'/%3E%3Cpath d='M0 520c151-78 289-67 413-15 112 46 215 58 353-7 169-80 294-79 434-25v427H0Z' fill='url(%23duneA)'/%3E%3Cpath d='M0 689c106-51 249-52 367 15 108 61 207 62 343-4 171-82 333-109 490-55v255H0Z' fill='url(%23duneB)'/%3E%3Cpath d='M405 337c48-67 123-105 198-79 57 19 89 70 152 88 65 19 128-10 191-38-58 70-150 125-254 145-145 28-237-37-287-116Z' fill='%23ffda9f' fill-opacity='.38'/%3E%3C/svg%3E"
                />
              </div>
              <figcaption id="imageDescription">
                Captured during a low-light session in Wadi Rum. Shared with the
                travel collection and archived in high resolution.
              </figcaption>
            </figure>

            <div class="meta" aria-label="Image metadata">
              <span>4032 × 3024 px</span>
              <span>12.4 MB</span>
              <span>Edited yesterday</span>
            </div>

            <div class="actions">
              <button type="button" class="button-secondary">Download original</button>
              <button type="button" class="trigger" id="openDialogButton">
                Delete image
              </button>
            </div>

            <p class="status" id="statusMessage" aria-live="polite"></p>
          </div>
        </section>
      </main>
    </div>

    <dialog
      id="deleteDialog"
      aria-labelledby="deleteDialogTitle"
      aria-describedby="deleteDialogDescription"
    >
      <div class="dialog-body">
        <h2 id="deleteDialogTitle">Delete this image from your library?</h2>
        <p id="deleteDialogDescription">
          This removes <strong>Evening dune light</strong> from your library. You
          can keep the image by selecting Cancel.
        </p>
        <div class="dialog-actions">
          <button type="button" class="button-secondary" id="cancelDialogButton" autofocus>
            Cancel
          </button>
          <button type="button" class="button-danger" id="confirmDeleteButton">
            Delete image
          </button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById("deleteDialog");
      const trigger = document.getElementById("openDialogButton");
      const cancelButton = document.getElementById("cancelDialogButton");
      const confirmButton = document.getElementById("confirmDeleteButton");
      const imageCard = document.getElementById("imageCard");
      const statusMessage = document.getElementById("statusMessage");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        imageCard.classList.add("removed");
        trigger.disabled = true;
        statusMessage.textContent = "Image deleted from your library.";
        dialog.close("delete");
      });
    </script>
  </body>
</html>
