                />
              </div>
              <figcaption id="imageDescription">
                Captured during a low-light session in Wadi Rum. Shared with the
                travel collection and archived in high resolution.
              </figcaption>
            </figure>

            <div class="meta" aria-label="Image metadata">
              <span>4032 × 3024 px</span>
              <span>12.4 MB</span>
              <span>Edited yesterday</span>
            </div>

            <div class="actions">
              <button type="button" class="button-secondary">Download original</button>
              <button type="button" class="trigger" id="openDialogButton">
                Delete image
              </button>
            </div>

            <p class="status" id="statusMessage" role="status" tabindex="-1"></p>
          </div>
        </section>
      </main>
    </div>

    <dialog
      id="deleteDialog"
      aria-labelledby="deleteDialogTitle"
      aria-describedby="deleteDialogDescription"
    >
      <div class="dialog-body">
        <h2 id="deleteDialogTitle">Delete this image from your library?</h2>
        <p id="deleteDialogDescription">
          This removes <strong>Evening dune light</strong> from your library. You
          can keep the image by selecting Cancel.
        </p>
        <div class="dialog-actions">
          <button type="button" class="button-secondary" id="cancelDialogButton" autofocus>
            Cancel
          </button>
          <button type="button" class="button-danger" id="confirmDeleteButton">
            Delete image
          </button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById("deleteDialog");
      const trigger = document.getElementById("openDialogButton");
      const cancelButton = document.getElementById("cancelDialogButton");
      const confirmButton = document.getElementById("confirmDeleteButton");
      const imageCard = document.getElementById("imageCard");
      const statusMessage = document.getElementById("statusMessage");
      let pendingDeletion = false;

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        pendingDeletion = true;
        dialog.close("delete");
      });

      dialog.addEventListener("close", () => {
        if (!pendingDeletion) {
          return;
        }

        imageCard.classList.add("removed");
        trigger.disabled = true;
        statusMessage.textContent = "Image deleted from your library.";
        statusMessage.focus();
        pendingDeletion = false;
      });
    </script>
  </body>
